// SeaGuard configuration and shared helper library.
// Edit the values in `cfg` to change behaviour. Everything else reads from here.
// NOTE: coordinates of the boundary, reserve and harbour are ILLUSTRATIVE ONLY,
// chosen to make a realistic simulation. They are not navigational data.

const cfg = {
    version: '1.1.0',

    // Where Node-RED itself is reachable from Node-RED (used for the Wi-Fi sync
    // endpoint and the local Telegram / Open-Meteo mocks). Change the port if you
    // run Node-RED on something other than 1880.
    baseUrl: env.get('SEAGUARD_BASE_URL') || 'http://127.0.0.1:1880',

    // Telegram bot (optional). Leave token empty to keep everything on the local mock.
    // Test runs ALWAYS use the mock, so a real bot only receives live-mode alerts.
    telegram: {
        enabled: env.get('SEAGUARD_LIVE_TELEGRAM') === 'true',
        token: env.get('TELEGRAM_BOT_TOKEN') || '',
        familyChatId: env.get('TELEGRAM_FAMILY_CHAT') || '',
        coastGuardChatId: env.get('TELEGRAM_COASTGUARD_CHAT') || ''
    },

    harbour: { name: 'Home harbour', lat: 9.2876, lon: 79.3129, wifiRadiusM: 400 },
    boundary: {
        name: 'Maritime boundary (illustrative)',
        points: [[9.72, 79.47], [9.40, 79.50], [9.10, 79.53]],
        warnM: 1000,      // warn when closer than this on the home side
        warnExitM: 1300,  // hysteresis: only clear the warning beyond this
        returnM: 150      // hysteresis: a violation clears only this far back on the home side
    },
    reserve: {
        name: 'Coral reserve, no fishing (illustrative)',
        poly: [[9.37, 79.36], [9.37, 79.41], [9.34, 79.41], [9.34, 79.36]]
    },
    zones: [
        { id: 'Z1', name: 'Near-shore', lat: 9.35, lon: 79.35 },
        { id: 'Z2', name: 'Mid Palk Bay', lat: 9.50, lon: 79.40 },
        { id: 'Z3', name: 'Boundary waters', lat: 9.45, lon: 79.50 }
    ],
    fleet: [
        { id: 'B1', name: 'Sagar Rani', crew: ['Murugan', 'Selvam', 'Arul'] },
        { id: 'B2', name: 'Meenakshi', crew: ['Karthik', 'Anthony'] },
        { id: 'B3', name: 'Kadal Pura', crew: ['Ravi', 'Joseph', 'Manoj'] },
        { id: 'B4', name: 'Velankanni', crew: ['Sebastian', 'Kumar'] },
        { id: 'B5', name: 'Neela Megam', crew: ['Prakash', 'Irudayaraj', 'Siva'] }
    ],

    lora: {
        telemetryEveryS: 5,   // periodic uplink interval (duty-cycle friendly)
        baseLoss: 0.05,       // background packet loss
        lossPer10km: 0.02,    // extra loss per 10 km from the shore gateway
        dupProb: 0.02,        // background duplicate delivery
        delayProb: 0.25       // chance a packet arrives one tick late
    },
    detect: {
        capsizeRollDeg: 65, capsizeHoldS: 4,
        floodPct: 60, floodHoldS: 3,
        tagLostDbm: -95, mobMissingS: 8,
        commsLostS: 45,
        correlationWindowS: 90,
        cooldownS: 120,
        escalateAfterS: 60,
        updateMinGapS: 20,
        restoreGraceS: 15,
        gatewayHbTimeoutS: 15
    },
    storm: { waveM: 2.5, windKmh: 45, clearWaveM: 2.0, clearWindKmh: 35 },
    weather: {
        offline: env.get('SEAGUARD_LIVE_WEATHER') !== 'true',
        liveEverySec: 600,
        testEverySimS: 30,
        marineUrl: 'https://marine-api.open-meteo.com/v1/marine',
        forecastUrl: 'https://api.open-meteo.com/v1/forecast'
    },
    retry: { eventBackoff: [3, 3, 4, 5, 6], maxEventTries: 40, notifyBackoff: [2, 4, 8, 16], maxNotifyTries: 15 },
    sync: { batch: 50, timeoutS: 5 },
    speeds: { live: 5, test: 10 },
    test: { durationS: 360, drainS: 20 }
};

// ---------------------------------------------------------------- helpers
const DEG = Math.PI / 180, R = 6371000;
const ref = { lat: cfg.harbour.lat, lon: cfg.harbour.lon };
const cosRef = Math.cos(ref.lat * DEG);

function toXY(lat, lon) { return { x: (lon - ref.lon) * DEG * R * cosRef, y: (lat - ref.lat) * DEG * R }; }
function toLL(x, y) { return { lat: ref.lat + y / R / DEG, lon: ref.lon + x / (R * cosRef) / DEG }; }

const bXY = cfg.boundary.points.map(p => toXY(p[0], p[1]));
const home = { x: 0, y: 0 };

function segInfo(p, a, b) {
    const dx = b.x - a.x, dy = b.y - a.y, L2 = dx * dx + dy * dy;
    let u = ((p.x - a.x) * dx + (p.y - a.y) * dy) / L2;
    u = Math.max(0, Math.min(1, u));
    const fx = a.x + u * dx, fy = a.y + u * dy;
    return {
        d: Math.hypot(p.x - fx, p.y - fy), fx, fy,
        cross: dx * (p.y - a.y) - dy * (p.x - a.x),
        homeCross: dx * (home.y - a.y) - dy * (home.x - a.x)
    };
}
// Signed distance (m) to the boundary polyline: positive = home side, negative = crossed.
function boundaryDist(p) {
    let best = null;
    for (let i = 0; i < bXY.length - 1; i++) {
        const s = segInfo(p, bXY[i], bXY[i + 1]);
        if (!best || s.d < best.d) best = s;
    }
    return Math.sign(best.cross) === Math.sign(best.homeCross) ? best.d : -best.d;
}
// A point at signed distance d from the boundary, at northing y. Also returns the unit
// normal (nx, ny) pointing towards the home side.
function boundaryPoint(y, d) {
    for (let i = 0; i < bXY.length - 1; i++) {
        const a = bXY[i], b = bXY[i + 1];
        const lo = Math.min(a.y, b.y), hi = Math.max(a.y, b.y);
        if (y >= lo && y <= hi) {
            const u = (y - a.y) / (b.y - a.y);
            const fx = a.x + u * (b.x - a.x), fy = y;
            let nx = -(b.y - a.y), ny = (b.x - a.x);
            const L = Math.hypot(nx, ny); nx /= L; ny /= L;
            if (nx * (home.x - fx) + ny * (home.y - fy) < 0) { nx = -nx; ny = -ny; }
            return { x: fx + nx * d, y: fy + ny * d, nx, ny };
        }
    }
    return null;
}
const reserveXY = cfg.reserve.poly.map(p => toXY(p[0], p[1]));
function inPoly(p, poly) {
    let c = false;
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
        const a = poly[i], b = poly[j];
        if (((a.y > p.y) !== (b.y > p.y)) && (p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x)) c = !c;
    }
    return c;
}
function inReserve(p) { return inPoly(p, reserveXY); }
// Distance from a point outside the polygon to its nearest edge (0 if inside).
function reserveDist(p) {
    if (inReserve(p)) return 0;
    let best = Infinity;
    for (let i = 0; i < reserveXY.length; i++) {
        const s = segInfo(p, reserveXY[i], reserveXY[(i + 1) % reserveXY.length]);
        best = Math.min(best, s.d);
    }
    return best;
}
const zonesXY = cfg.zones.map(z => Object.assign({}, z, toXY(z.lat, z.lon)));
function zoneOfXY(p) {
    let best = null, bd = Infinity;
    for (const z of zonesXY) { const d = Math.hypot(p.x - z.x, p.y - z.y); if (d < bd) { bd = d; best = z.id; } }
    return best;
}
function zoneOf(lat, lon) { return zoneOfXY(toXY(lat, lon)); }
function zoneName(id) { const z = cfg.zones.find(z => z.id === id); return z ? z.name : id; }

// Seeded PRNG (mulberry32) so a test campaign can be replayed from its seed.
function rng(seed) {
    let a = seed >>> 0;
    return function () {
        a |= 0; a = a + 0x6D2B79F5 | 0;
        let t = Math.imul(a ^ a >>> 15, 1 | a);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
}
function gauss(r) {
    let u = 0, v = 0;
    while (u === 0) u = r();
    while (v === 0) v = r();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function activeFaults(faults, t, boat) {
    return (faults || []).filter(f => (boat === undefined || f.boat === boat) && t >= f.start && t < f.end);
}
function findFault(faults, t, boat, type) {
    return (faults || []).find(f => f.type === type && (boat == null || f.boat === boat) && t >= f.start && t < f.end) || null;
}
// "Ground truth" sea state used by the Open-Meteo mock and by the boat physics in test runs.
function mockSea(zoneId, t, faults) {
    const zi = cfg.zones.findIndex(z => z.id === zoneId);
    let wave = 0.55 + 0.08 * Math.sin(t / 97 + zi), wind = 17 + 3 * Math.sin(t / 131 + zi * 2);
    let gust = wind * 1.3;
    const s = (faults || []).find(f => f.type === 'STORM' && f.params.zone === zoneId && t >= f.start && t < f.end);
    if (s) { wave = s.params.wave; wind = s.params.wind; gust = s.params.wind * 1.35; }
    return { wave: +wave.toFixed(2), wind: +wind.toFixed(1), gust: +gust.toFixed(1) };
}
function boatName(id) { const b = cfg.fleet.find(b => b.id === id); return b ? b.name : id; }
function fmtLL(lat, lon) { return lat.toFixed(4) + ' N, ' + lon.toFixed(4) + ' E'; }

const lib = {
    toXY, toLL, boundaryDist, boundaryPoint, inReserve, reserveDist, reserveXY, zoneOf, zoneOfXY, zoneName,
    rng, gauss, activeFaults, findFault, mockSea, boatName, fmtLL, bXY
};

global.set('cfg', cfg);
global.set('lib', lib);
if (global.get('epoch') === undefined) global.set('epoch', 0);
node.status({ fill: 'green', shape: 'dot', text: 'SeaGuard ' + cfg.version + ' configured' });
// Start the system in live mode once configured.
return { topic: 'cmd', payload: { cmd: 'live' } };

// Boat firmware (runs "on the boat hub"). Consumes raw sensor readings and:
//  - detects capsize / flooding / man-overboard / SOS with debounce so transients are ignored
//  - sends periodic telemetry over LoRa (unconfirmed) and critical events as confirmed
//    uplinks that are retried with backoff until the shore acknowledges them
//  - keeps a full-resolution onboard log and syncs it over harbour Wi-Fi in batches
// Outputs: 1 = LoRa uplink, 2 = Wi-Fi sync request, 3 = diagnostics
const cfg = global.get('cfg');
const ep = global.get('epoch');
const D = cfg.detect;

let S = context.get('S');
if (!S || S.ep !== ep) { S = { ep, boats: {} }; context.set('S', S); }

function state(id) {
    if (S.boats[id]) return S.boats[id];
    const lb = ((global.get('layout') || {}).boats || []).find(b => b.id === id) || {};
    const st = {
        id, seq: 0, lastTelem: -999, hold: { roll: 0, flood: 0 }, latched: { capsize: false, flood: false },
        tags: {}, evN: 0, pending: [], log: [], logSeq: 0, acked: 0, inflight: null, batchN: 0,
        adv: null, advCount: 0,
        stats: { sent: 0, retries: 0, acked: 0, gaveUp: 0, rttSum: 0, rttN: 0, dupAcks: 0,
            filtered: { roll: 0, splash: 0, tag: 0 }, syncBatches: 0, syncTimeouts: 0, syncErrors: 0 }
    };
    // Records already logged earlier in the trip (before this simulation window started).
    const pre = lb.preLog || 0;
    const ll = lb.startLL || { lat: cfg.harbour.lat, lon: cfg.harbour.lon };
    for (let i = 0; i < pre; i++) {
        st.log.push({ s: ++st.logSeq, t: -(pre - i), lat: ll.lat, lon: ll.lon, spd: 0, roll: 0, lvl: 2, bat: 12.6, crew: (lb.tags || []).length });
    }
    S.boats[id] = st;
    return st;
}
function backoff(n) { const b = cfg.retry.eventBackoff; return b[Math.min(n - 1, b.length - 1)]; }

const up = [], sync = [], diag = [];
const t = global.get('simTime') || 0;

function publishSummary(b) {
    const fw = global.get('fw') || {};
    fw[b.id] = {
        pending: b.pending.map(p => ({ eid: p.eid, ev: p.pkt.ev, tries: p.tries })),
        sent: b.stats.sent, retries: b.stats.retries, acked: b.stats.acked, gaveUp: b.stats.gaveUp, dupAcks: b.stats.dupAcks,
        avgAckS: b.stats.rttN ? +(b.stats.rttSum / b.stats.rttN).toFixed(1) : null,
        filtered: b.stats.filtered, logBuffered: b.log.length, logSeq: b.logSeq, syncedThrough: b.acked,
        syncBatches: b.stats.syncBatches, syncTimeouts: b.stats.syncTimeouts, syncErrors: b.stats.syncErrors,
        adv: b.adv, advCount: b.advCount, seq: b.seq
    };
    global.set('fw', fw);
}

if (msg.topic === 'downlink') {
    const d = msg.payload || {};
    if (d.ep !== ep || !d.b) return null;
    const b = state(d.b);
    if (d.k === 'A') {
        const i = b.pending.findIndex(p => p.eid === d.eid);
        if (i >= 0) {
            const p = b.pending[i];
            b.pending.splice(i, 1);
            b.stats.acked++; b.stats.rttSum += (t - p.firstAt); b.stats.rttN++;
            diag.push({ boat: b.id, t, text: `Shore acknowledged ${p.pkt.ev} (${p.eid}) after ${p.tries} transmission(s), ${t - p.firstAt}s` });
        } else b.stats.dupAcks++;
    } else if (d.k === 'ADV') {
        b.adv = { text: d.text, level: d.level, t }; b.advCount++;
        diag.push({ boat: b.id, t, text: `Advisory shown on deck display: ${d.text}` });
    }
    publishSummary(b);
    return [null, null, diag.length ? diag.map(x => ({ topic: 'diag', payload: x })) : null];
}

if (msg.topic === 'syncResp') {
    const bId = msg.boat;
    if (msg.ep !== ep || !bId) return null;
    const b = state(bId);
    if (msg._syncBatch !== undefined && (!b.inflight || msg._syncBatch !== b.inflight.id)) return null;
    if (msg.statusCode === 200 && msg.payload && Number.isSafeInteger(msg.payload.ackedThrough) && msg.payload.ackedThrough >= 0 && msg.payload.ackedThrough <= b.logSeq && b.inflight && msg.payload.ackedThrough <= b.inflight.to) {
        const a = msg.payload.ackedThrough;
        if (a > b.acked) b.acked = a;
        let k = 0; while (k < b.log.length && b.log[k].s <= b.acked) k++;
        if (k) b.log.splice(0, k);
        b.inflight = null;
    } else {
        b.stats.syncErrors++;
        b.inflight = null;
    }
    publishSummary(b);
    return null;
}

if (msg.topic !== 'reading') return null;
const r = msg.payload;
if (r.ep !== ep) return null;
const b = state(r.boat);

function sendPkt(pkt, isRetry) {
    up.push({ topic: 'uplink', payload: Object.assign({}, pkt) });
    b.stats.sent++;
    if (isRetry) b.stats.retries++;
}
function raise(type, data) {
    const eid = b.id + '-' + (++b.evN);
    const pkt = { k: 'E', ev: type, eid, b: b.id, ep, s: ++b.seq, t: r.t, la: r.gps.lat, lo: r.gps.lon, d: data, rt: 1 };
    b.pending.push({ eid, pkt, tries: 1, firstAt: r.t, nextAt: r.t + backoff(1) });
    sendPkt(pkt, false);
    diag.push({ boat: b.id, t: r.t, text: `Edge detected ${type}; confirmed uplink ${eid} sent` });
}

// ---- onboard log (1 Hz, full resolution)
const aboard = r.ble.filter(x => x.rssi !== null && x.rssi >= D.tagLostDbm).length;
// A test freezes new log production during its final drain window. The real radio/HTTP
// path continues so the oracle can require complete delivery, rather than tolerate loss.
const testState = global.get('test') || {};
if (global.get('mode') !== 'test' || !testState.measurementEnd || r.t <= testState.measurementEnd) {
    b.log.push({ s: ++b.logSeq, t: r.t, lat: +r.gps.lat.toFixed(6), lon: +r.gps.lon.toFixed(6), spd: r.gps.spd, roll: r.imu.roll, lvl: r.water.level, bat: r.bat.v, crew: aboard });
}
if (b.log.length > 20000) b.log.shift();

// ---- capsize: roll beyond threshold held for capsizeHoldS
if (Math.abs(r.imu.roll) > D.capsizeRollDeg) b.hold.roll++;
else {
    if (b.hold.roll > 0 && b.hold.roll < D.capsizeHoldS && !b.latched.capsize) {
        b.stats.filtered.roll++;
        diag.push({ boat: b.id, t: r.t, text: `Ignored roll spike (${b.hold.roll}s above ${D.capsizeRollDeg} deg): not a capsize` });
    }
    b.hold.roll = 0;
}
if (b.hold.roll >= D.capsizeHoldS && !b.latched.capsize) { b.latched.capsize = true; raise('CAPSIZE', { roll: Math.round(r.imu.roll) }); }

// ---- flooding: bilge level above threshold held for floodHoldS
if (r.water.level > D.floodPct) b.hold.flood++;
else {
    if (b.hold.flood > 0 && b.hold.flood < D.floodHoldS && !b.latched.flood) {
        b.stats.filtered.splash++;
        diag.push({ boat: b.id, t: r.t, text: `Ignored bilge splash (${b.hold.flood}s above ${D.floodPct}%): not flooding` });
    }
    b.hold.flood = 0;
}
if (b.hold.flood >= D.floodHoldS && !b.latched.flood) { b.latched.flood = true; raise('FLOODING', { level: Math.round(r.water.level) }); }

// ---- man overboard: crew tag missing for mobMissingS
for (const tg of r.ble) {
    const ts = b.tags[tg.tag] || (b.tags[tg.tag] = { miss: 0, latched: false });
    const lost = tg.rssi === null || tg.rssi < D.tagLostDbm;
    if (lost) ts.miss++;
    else {
        if (ts.miss > 0 && ts.miss < D.mobMissingS && !ts.latched) {
            b.stats.filtered.tag++;
            diag.push({ boat: b.id, t: r.t, text: `Ignored tag dropout for ${tg.name} (${ts.miss}s): tag came back` });
        }
        ts.miss = 0;
    }
    if (ts.miss >= D.mobMissingS && !ts.latched) { ts.latched = true; raise('MOB', { tag: tg.tag, crew: tg.name }); }
}

// ---- SOS button
if (r.sos) raise('SOS', {});

// ---- periodic telemetry (unconfirmed)
if (r.t - b.lastTelem >= cfg.lora.telemetryEveryS) {
    b.lastTelem = r.t;
    sendPkt({ k: 'T', b: b.id, ep, s: ++b.seq, t: r.t, la: +r.gps.lat.toFixed(6), lo: +r.gps.lon.toFixed(6), sp: r.gps.spd, hd: r.gps.hdg,
        r: r.imu.roll, wl: r.water.level, bv: r.bat.v, cr: aboard, ct: r.ble.length, hdop: r.gps.hdop }, false);
}

// ---- retransmit unacknowledged confirmed events (same sequence number, like LoRaWAN)
for (const p of b.pending) {
    if (r.t >= p.nextAt) {
        if (p.tries >= cfg.retry.maxEventTries) {
            p.gaveUp = true; b.stats.gaveUp++;
            diag.push({ boat: b.id, t: r.t, text: `Gave up on ${p.eid} after ${p.tries} transmissions` });
        } else {
            p.tries++; p.pkt.rt = p.tries;
            sendPkt(p.pkt, true);
            p.nextAt = r.t + backoff(p.tries);
        }
    }
}
b.pending = b.pending.filter(p => !p.gaveUp);

// ---- harbour Wi-Fi: batch sync of the onboard log (one batch in flight)
if (r.inHarbour) {
    if (b.inflight && r.t - b.inflight.sentAt > cfg.sync.timeoutS) {
        b.stats.syncTimeouts++;
        diag.push({ boat: b.id, t: r.t, text: `Wi-Fi sync batch #${b.inflight.id} timed out; resending from record ${b.acked + 1}` });
        b.inflight = null;
    }
    if (!b.inflight && b.log.length) {
        const batch = b.log.slice(0, cfg.sync.batch);
        b.inflight = { id: ++b.batchN, sentAt: r.t, from: batch[0].s, to: batch[batch.length - 1].s };
        b.stats.syncBatches++;
        sync.push({
            topic: 'sync', boat: b.id, ep, _syncBatch: b.inflight.id, url: cfg.baseUrl + '/seaguard/sync',
            headers: { 'content-type': 'application/json' }, requestTimeout: 5000,
            payload: { boat: b.id, ep, batch: b.inflight.id, records: batch }
        });
    }
}

publishSummary(b);
return [up.length ? up : null, sync.length ? sync : null, diag.length ? diag.map(x => ({ topic: 'diag', payload: x })) : null];

// Boat physics + sensor model (the "real world" the IoT nodes measure).
// Produces one raw sensor reading per boat per simulated second.
// Faults injected by the test harness change the physical truth here
// (a capsize really rolls the boat over, a man overboard really removes the tag).
if (msg.topic !== 'tick') return null;
const cfg = global.get('cfg'), lib = global.get('lib');
const t = msg.t, ep = global.get('epoch');
const layout = global.get('layout');
if (!layout) return null;

let S = context.get('S');
if (!S || S.ep !== ep) {
    const r = lib.rng(((global.get('runSeed') || 12345) + 101) >>> 0);
    const boats = {};
    for (const b of layout.boats) {
        boats[b.id] = Object.assign({}, b, {
            center: b.center ? Object.assign({}, b.center) : { x: b.x, y: b.y },
            target: b.target ? Object.assign({}, b.target) : null,
            hdg: b.hdg || 0, spd: b.spd || 0,
            rollPhase: r() * 6, bat: 12.75 - r() * 0.25,
            capsized: false, capRoll: 0, flooding: false, floodLevel: 0,
            tags: b.tags.map(tg => Object.assign({}, tg, { overboard: false }))
        });
    }
    S = { ep, r, boats };
    context.set('S', S);
}
const r = S.r;
const faults = global.get('faults') || [];
const mode = global.get('mode');
const seaState = global.get('seaState') || {};
const dock = { x: 0, y: 40 };
const out = [];
const truth = {};

function steerTo(B, p, spd) {
    B.hdg = Math.atan2(p.x - B.x, p.y - B.y);
    B.spd = spd;
    return Math.hypot(p.x - B.x, p.y - B.y);
}
function sampleFishingSpot() {
    for (let i = 0; i < 200; i++) {
        const p = { x: 3000 + r() * 11500, y: 4000 + r() * 24000 };
        if (lib.boundaryDist(p) > 4000 && lib.reserveDist(p) > 800) return p;
    }
    return { x: 8000, y: 15000 };
}

for (const id of Object.keys(S.boats)) {
    const B = S.boats[id];
    const has = type => lib.findFault(faults, t, id, type);

    // ---- navigation
    const drift = has('BOUNDARY_DRIFT'), incursion = has('RESERVE_INCURSION');
    if (B.capsized) { B.spd = 0.3; B.hdg += lib.gauss(r) * 0.05; B.mode = 'distress'; }
    else if (drift) {
        const bp = lib.boundaryPoint(B.y, 0);
        if (bp) B.hdg = Math.atan2(-bp.nx, -bp.ny);
        B.spd = drift.params.speed; B.mode = 'transit';
    } else if (incursion) {
