                chanDropUp: cu.dropped || 0, chanDupUp: cu.dup || 0, chanHeldUp: cu.held || 0, chanDropDown: cd.dropped || 0,
                hist: (linkHist[b.id] || []).map(h => ({ t: h.t0, n: h.n, lost: h.lost })) };
